 tx.exec("INSERT INTO trading.qt_desk_accounting_inputs(input_id,decision_id,producer_id,policy_version,source_version,as_of,valid_until,content_digest,payload) SELECT "+tx.quote(input_id)+"::uuid,"+tx.quote(text(d.at("decision_id")))+"::uuid,producer_id,policy_version,"+tx.quote("qt-first-day-input/"+input_id)+",as_of,valid_until,"+tx.quote(hash(in))+","+tx.quote(in.dump())+"::jsonb FROM trading.qt_desk_market_sources WHERE source_id="+tx.quote(market_id)+"::uuid");
